theme.css:
/* theme: Double Fault | A government win and a tech triumph shared the day with a court maneuver and a chip selloff, leaving winners and losers trading blows on the same page. */
/* mood: tense */
/* layout: hero=split; major-events=timeline/stack; political-news=numbered/stack; financial-news=stat/stack; tech-news=outline/grid-2; entertainment-news=plain/stack; sports=split/masonry; music-releases=plain/stack; stock-analysis=stat/grid-3; outlook=tile/grid-2 */

.diary-page {
  --paper: #fbf0d9;
  --paper-alt: #f5e3c3;
  --ink: #241a0e;
  --ink-soft: #4a3b28;
  --muted: #6b5840;
  --accent: #8f4000;
  --accent-ink: #fff6ea;
  --rule: #d9b98a;
  --font-display: var(--ff-fraunces), Georgia, serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-inter), system-ui, sans-serif;

  background: var(--paper);
  color: var(--ink-soft);
}

/* Hero: split, with a hard championship stripe under it */
.diary-page .diary-hero {
  background: var(--paper-alt);
  border-bottom: 8px double var(--accent);
}

.diary-page .diary-hero-inner {
  padding-block: 2.5rem 3.5rem;
}

.diary-page .diary-kicker {
  font-family: var(--font-ui);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.22em;
  color: var(--accent);
}

.diary-page .diary-title {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: clamp(2.5rem, 6vw, 4.75rem);
  line-height: 1;
  letter-spacing: -0.03em;
  color: var(--ink);
}

.diary-page .diary-summary {
  font-size: clamp(1.1rem, 1.8vw, 1.35rem);
  line-height: 1.6;
  color: var(--ink-soft);
  border-left: 4px solid var(--accent);
  padding-left: 1.25rem;
}

.diary-page .diary-theme-note {
  font-family: var(--font-ui);
  font-size: 0.85rem;
  color: var(--muted);
}

.diary-page .diary-theme-name {
  background: var(--accent);
  color: var(--accent-ink);
  font-weight: 700;
  letter-spacing: 0.08em;
}

/* Contents: amber pill for the active section */
.diary-page .diary-toc {
  background: var(--paper);
  border-bottom: 2px solid var(--rule);
}

.diary-page .diary-toc-link.is-active {
  color: var(--accent);
  font-weight: 600;
}

.diary-page .diary-toc-number {
  color: var(--accent);
}

@media (min-width: 1024px) {
  .diary-page .diary-toc-link.is-active {
    border-left-color: var(--accent);
  }
}

/* Section heads: scored like a match */
.diary-page .diary-section-head {
  border-bottom: 3px solid var(--ink);
  padding-bottom: 0.75rem;
  margin-bottom: 2rem;
}

.diary-page .diary-section-number {
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-weight: 800;
  color: var(--accent);
}

.diary-page .diary-section-title {
  font-family: var(--font-display);
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--ink);
}

/* Major Events: timeline, a long rally on a rail */
.diary-page [data-section="major-events"] .diary-stories {
  max-width: 44rem;
  gap: 0;
}

.diary-page [data-section="major-events"] .diary-card {
  position: relative;
  padding-left: 2.25rem;
  margin-bottom: 1.75rem;
}

.diary-page [data-section="major-events"] .diary-card::before {
  content: "";
  position: absolute;
  left: 0.35rem;
  top: 0.5rem;
  bottom: -1.75rem;
  width: 2px;
  background: var(--rule);
}

.diary-page [data-section="major-events"] .diary-card:last-child::before {
  bottom: 0;
}

.diary-page [data-section="major-events"] .diary-card::after {
  content: "";
  position: absolute;
  left: 0;
  top: 0.6rem;
  width: 0.8rem;
  height: 0.8rem;
  border-radius: 50%;
  background: var(--accent);
  border: 3px solid var(--paper);
}

.diary-page [data-section="major-events"] .diary-card-inner {
  gap: 0.4rem;
}

.diary-page [data-section="major-events"] .diary-card-title {
  font-size: 1.55rem;
  font-weight: 700;
  line-height: 1.15;
  color: var(--ink);
}

.diary-page [data-section="major-events"] .diary-card-body {
  font-size: 1.1rem;
  line-height: 1.7;
}

.diary-page [data-section="major-events"] .diary-card-thread {
  border-color: var(--accent);
  color: var(--accent);
  font-family: var(--font-ui);
  font-size: 0.75rem;
  font-weight: 600;
}

.diary-page [data-section="major-events"] .diary-card-thread:hover {
  background: var(--accent);
  color: var(--accent-ink);
}

/* Political News: numbered, a two-sided ledger */
.diary-page [data-section="political-news"] .diary-card-inner {
  display: grid;
  grid-template-columns: 3.5rem minmax(0, 1fr);
  column-gap: 1.25rem;
  row-gap: 0.6rem;
  align-items: start;
  border-top: 1px solid var(--rule);
  padding-top: 1.25rem;
}

.diary-page [data-section="political-news"] .diary-card-index {
  grid-row: 1 / -1;
  font-family: var(--font-display);
  font-size: 3.25rem;
  font-weight: 800;
  line-height: 0.85;
  color: var(--accent);
  font-variant-numeric: tabular-nums;
}

.diary-page [data-section="political-news"] .diary-card-title {
  font-size: 1.7rem;
  font-weight: 700;
  color: var(--ink);
}

.diary-page [data-section="political-news"] .diary-card-body {
  font-size: 1.15rem;
  line-height: 1.75;
}

/* Financial News: stat, a swing in the score */
.diary-page [data-section="financial-news"] .diary-card-inner {
  border-top: 6px solid var(--accent);
  padding-top: 1.25rem;
}

.diary-page [data-section="financial-news"] .diary-card-figure {
  font-family: var(--font-display);
  font-size: clamp(3rem, 10cqi, 4.5rem);
  font-weight: 800;
  line-height: 0.95;
  letter-spacing: -0.03em;
  color: var(--accent);
}

.diary-page [data-section="financial-news"] .diary-card-title {
  font-size: 1.8rem;
  font-weight: 700;
  color: var(--ink);
}

.diary-page [data-section="financial-news"] .diary-card-body {
  font-size: 1.15rem;
  line-height: 1.75;
}

/* Tech News: outlined cards, a grid of callouts */
.diary-page [data-section="tech-news"] .diary-card-inner {
  padding: 1.5rem;
  border: 2px solid var(--rule);
  border-radius: 0;
  background: var(--paper);
}

.diary-page [data-section="tech-news"] .diary-card-title {
  font-size: 1.3rem;
  font-weight: 700;
  line-height: 1.2;
  color: var(--ink);
}

.diary-page [data-section="tech-news"] .diary-card-body {
  font-size: 1.05rem;
  line-height: 1.65;
}

.diary-page [data-section="tech-news"] .diary-card-thread {
  border-color: var(--accent);
  color: var(--accent);
  font-family: var(--font-ui);
}

.diary-page [data-section="tech-news"] .diary-card-thread:hover {
  background: var(--accent);
  color: var(--accent-ink);
}

/* Entertainment: plain, a column of news items with a left accent */
.diary-page [data-section="entertainment-news"] .diary-stories--stack {
  max-width: 44rem;
}

.diary-page [data-section="entertainment-news"] .diary-card--plain .diary-card-inner {
  border-left: 4px solid var(--accent);
  padding-left: 1.25rem;
}

.diary-page [data-section="entertainment-news"] .diary-card-title {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--ink);
}

.diary-page [data-section="entertainment-news"] .diary-card-body {
  font-size: 1.1rem;
  line-height: 1.7;
}

/* Sports: split cards in a masonry, a box score column */
.diary-page [data-section="sports"] .diary-stories--masonry {
  columns: 2 17rem;
  column-gap: 1.5rem;
}

.diary-page [data-section="sports"] .diary-card--split .diary-card-inner {
  padding-top: 1rem;
  border-top: 3px solid var(--ink);
}

.diary-page [data-section="sports"] .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.45rem;
  font-weight: 800;
  line-height: 1.1;
  color: var(--ink);
}

.diary-page [data-section="sports"] .diary-card-body {
  font-size: 1.05rem;
  line-height: 1.65;
}

.diary-page [data-section="sports"] .diary-card-thread {
  border-color: var(--accent);
  color: var(--accent);
  font-family: var(--font-ui);
  font-size: 0.72rem;
}

.diary-page [data-section="sports"] .diary-card-thread:hover {
  background: var(--accent);
  color: var(--accent-ink);
}

@container (min-width: 34rem) {
  .diary-page [data-section="sports"] .diary-card--split .diary-card-inner {
    grid-template-columns: minmax(7rem, 32%) minmax(0, 1fr);
    column-gap: 1.5rem;
  }
}

/* Music Releases: plain, unboxed, the songs on their own */
.diary-page [data-section="music-releases"] .diary-card--plain .diary-card-inner {
  border-bottom: 1px solid var(--rule);
  padding-bottom: 1.5rem;
}

.diary-page [data-section="music-releases"] .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.35rem;
  font-weight: 700;
  color: var(--ink);
}

.diary-page [data-section="music-releases"] .diary-card-body {
  font-size: 1.05rem;
  line-height: 1.65;
}

/* Stock Analysis: stat cards in a grid, the scoreboard */
.diary-page [data-section="stock-analysis"] .diary-stories--grid-3 {
  gap: 1.25rem;
}

.diary-page [data-section="stock-analysis"] .diary-card-inner {
  border-top: 4px solid var(--accent);
  padding-top: 0.9rem;
}

.diary-page [data-section="stock-analysis"] .diary-card-figure {
  font-family: var(--font-display);
  font-size: clamp(1.75rem, 8cqi, 2.75rem);
  font-weight: 800;
  line-height: 1;
  letter-spacing: -0.02em;
  color: var(--accent);
}

.diary-page [data-section="stock-analysis"] .diary-card-title {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--ink);
}

.diary-page [data-section="stock-analysis"] .diary-card-body {
  font-size: 1rem;
  line-height: 1.6;
}

/* Outlook: tile, the quiet forecast panel */
.diary-page [data-section="outlook"] .diary-card-inner {
  padding: 1.5rem 1.75rem;
  background: var(--paper-alt);
  border: 2px solid var(--rule);
}

.diary-page [data-section="outlook"] .diary-card-title {
  font-size: 1.4rem;
  font-weight: 700;
  color: var(--ink);
  margin-bottom: 0.5rem;
}

.diary-page [data-section="outlook"] .diary-card-body {
  font-size: 1.05rem;
  line-height: 1.65;
}

/* Markets strip: the tape on amber */
.diary-page .diary-markets-wrap {
  margin-bottom: 2rem;
}

.diary-page .diary-markets-label {
  font-family: var(--font-ui);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.16em;
  color: var(--muted);
}

.diary-page .diary-markets {
  gap: 0.75rem;
}

.diary-page .diary-spark {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
  border-radius: 0;
}

.diary-page .diary-spark-label {
  color: var(--muted);
  font-family: var(--font-ui);
}

.diary-page .diary-spark-value {
  color: var(--ink);
  font-family: var(--font-ui);
}

.diary-page .diary-spark-change {
  font-family: var(--font-ui);
}

.diary-page .diary-spark.is-up .diary-spark-change {
  color: #11652f;
}

.diary-page .diary-spark.is-down .diary-spark-change {
  color: var(--accent);
}

.diary-page .diary-spark-line {
  color: var(--accent);
}

.diary-page .diary-spark.is-up .diary-spark-line {
  color: #11652f;
}

/* Shared text styles */
.diary-page .diary-prose {
  font-size: 1.12rem;
  line-height: 1.75;
}

.diary-page .diary-prose a {
  font-family: var(--font-ui);
  font-size: 0.7em;
  font-weight: 600;
  letter-spacing: 0.05em;
  color: var(--accent);
  border-bottom: 1px solid currentColor;
  text-transform: uppercase;
}

.diary-page .diary-prose a:hover {
  color: var(--ink);
}

.diary-page .diary-prose strong {
  color: var(--ink);
  font-weight: 600;
}

.diary-page .diary-prose blockquote {
  border-left-color: var(--accent);
  color: var(--ink);
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
}

.diary-page .diary-prose ol > li::marker {
  color: var(--accent);
}

.diary-page .diary-card-thread {
  font-family: var(--font-ui);
  border: 1px solid var(--accent);
  color: var(--accent);
}

.diary-page .diary-card-thread:hover {
  background: var(--accent);
  color: var(--accent-ink);
}

/* Footer: a double rule to match the hero */
.diary-page .diary-footer {
  border-top: 4px double var(--accent);
  font-family: var(--font-ui);
  font-size: 0.85rem;
  color: var(--muted);
}

.diary-page .diary-footer a {
  color: var(--ink);
  font-weight: 600;
}

.diary-page .diary-footer a:hover {
  color: var(--accent);
}

/* Drop cap opening: kept, but amber */
.diary-page .diary-section:first-child .diary-card--plain:first-child .diary-prose > p:first-of-type::first-letter {
  font-family: var(--font-display);
  color: var(--accent);
}

/* Range of decorative flourishes: a corner mark on each section from the match theme */
.diary-page .diary-section {
  position: relative;
}

.diary-page .diary-section::before {
  content: "—";
  position: absolute;
  top: 1.25rem;
  right: 0;
  font-family: var(--font-display);
  font-size: 1.5rem;
  color: var(--rule);
  display: none;
}

@media (min-width: 400px) {
  .diary-page .diary-section::before {
    display: block;
  }
}

/* Make the daily mood unmistakable: a thin amber top border on the whole page */
.diary-page {
  box-shadow: inset 0 6px 0 var(--accent);
  border-top: 6px solid var(--accent);
}

/* Keep the reading width from getting too wide in stacked sections */
.diary-page [data-layout="stack"] .diary-stories {
  max-width: 46rem;
}

/* Ensure card bodies are comfortable on phones */
@container (max-width: 22rem) {
  .diary-page .diary-card-body {
    font-size: 1rem;
    line-height: 1.65;
  }
}
